export function TopicIcon({ topicId, subjectId, ...props }: SvgIconProps & { topicId: string; subjectId: string }) {
  const name = iconByTopicId[topicId];
  if (!name) return <SubjectIcon subjectId={subjectId} {...props} />;
  return (
    <SvgIcon
      {...props}
      viewBox="0 0 24 24"
      data-topic-icon={topicId}
      data-icon-name={name}
      aria-hidden="true"
      focusable="false"
      titleAccess={undefined}
    >
      <g fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
        {icons[name]}
      </g>
    </SvgIcon>
  );
}
